(()=>{const en=document.documentElement.lang==='en';let look='neon';try{look=localStorage.getItem('pa-look')||look}catch{}const field=document.createElement('div');field.className='light-field';field.setAttribute('aria-hidden','true');document.body.prepend(field);const controls=document.createElement('div');controls.className='visual-switch';controls.setAttribute('role','group');controls.setAttribute('aria-label',en?'Visual style':'Визуальный стиль');controls.innerHTML='<span>'+(en?'LIGHT MODE':'РЕЖИМ СВЕТА')+'</span><button data-look="base">'+(en?'Base':'Базовый')+'</button><button data-look="neon">'+(en?'Neon':'Неон')+'</button>';(document.querySelector('.hero-copy')||document.querySelector('footer')).append(controls);function apply(){document.body.dataset.look=look;controls.querySelectorAll('button').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.look===look)))}controls.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;look=b.dataset.look;apply();try{localStorage.setItem('pa-look',look)}catch{}});apply();let pending=false,x=0,y=0;function draw(){pending=false;if(!window.paMotion||look!=='neon')return;field.style.setProperty('--light-x',x+'px');field.style.setProperty('--light-y',y+'px');field.style.setProperty('--light-turn',Math.min(100,scrollY/55)+'deg')}function schedule(){if(!pending){pending=true;requestAnimationFrame(draw)}}if(matchMedia('(hover:hover)').matches)addEventListener('pointermove',e=>{x=(e.clientX/innerWidth-.5)*35;y=(e.clientY/innerHeight-.5)*25;schedule()},{passive:true});addEventListener('scroll',schedule,{passive:true});draw()})();
